Dinner dinner(String table) throws Exception {
    try (ExecutorService vt = Executors.newVirtualThreadPerTaskExecutor()) {
        Future<Soup> soup = vt.submit(() -> soupPot.serve(table));      // 1. three blocking calls,
        Future<Roast> roast = vt.submit(() -> oven.carve(table));       //    one virtual thread each
        Future<Salad> salad = vt.submit(() -> salads.toss(table));
        long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(800);
        try {
            return new Dinner(                                           // 2. one shared deadline
                soup.get(remaining(deadline), TimeUnit.NANOSECONDS),
                roast.get(remaining(deadline), TimeUnit.NANOSECONDS),
                salad.get(remaining(deadline), TimeUnit.NANOSECONDS));
        } catch (TimeoutException | ExecutionException e) {
            soup.cancel(true); roast.cancel(true); salad.cancel(true);  // 3. cancel by hand
            throw e;
        }
    }   // close() waits for every task
}

