suspend fun dinner(table: String): Dinner = withTimeout(800) {   // 2. one shared deadline
    coroutineScope {
        val soup = async { soupPot.serve(table) }                // 1. three suspending calls,
        val roast = async { oven.carve(table) }                  //    one coroutine each
        val salad = async { salads.toss(table) }
        Dinner(soup.await(), roast.await(), salad.await())
    }   // 3. a timeout or a failure cancels the other two automatically
}

