class PantryDoor(private val pantry: Pantry) : AutoCloseable {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)

    fun stockAsync(item: String): CompletableFuture<Int> =
        scope.future { pantry.stock(item) }

    fun stockMono(item: String): Mono<Int> =
        mono { pantry.stock(item) }

    override fun close() = scope.cancel()
}

