// Java equivalent: the Java and Reactor callers of those doors
class PantryCaller {
    private final PantryDoor door;
    PantryCaller(PantryDoor door) { this.door = door; }

    int stockBlocking(String item) throws Exception {
        return door.stockAsync(item).get(2, TimeUnit.SECONDS);   // blocks this thread: fine on a virtual thread
    }

    Mono<String> describe(String item) {
        return door.stockMono(item).map(n -> item + ": " + n + " left");   // cold, cancellable
    }
}
